func TestTCK_0004_lending_001(t *testing.T) {
	d := mustParse("testdata/tck/TestCases/compliance-level-3/0004-lending/0004-lending.dmn")
	inputs := map[string]any{
		"ApplicantData":       map[string]any{"Monthly": "", "Age": float64(35), "ExistingCustomer": true, "MaritalStatus": "M", "EmploymentStatus": "EMPLOYED"},
		"RequestedProduct":    map[string]any{"ProductType": "STANDARD LOAN", "Amount": float64(350000), "Rate": float64(0.0395), "Term": float64(360)},
		"BureauData":          map[string]any{"CreditScore": float64(649), "Bankrupt": false},
		"SupportingDocuments": "YES",
	}
	result, err := d.Evaluate(inputs)
	require.NoError(t, err)
	require.Equal(t, "ACCEPT", result["d_Adjudication"])
	require.Equal(t, float64(130), result["d_ApplicationRiskScore"])
	require.Equal(t, "LOW", result["d_Pre-bureauRiskCategory"])
	require.Equal(t, "MINI", result["d_BureauCallType"])
	require.Equal(t, "LOW", result["d_Post-bureauRiskCategory"])
	require.Equal(t, float64(1680.880325608555), result["d_RequiredMonthlyInstallment"])
	require.Equal(t, true, result["d_Pre-bureauAffordability"])
	require.Equal(t, "ELIGIBLE", result["d_Eligibility"])
	require.Equal(t, "BUREAU", result["d_Strategy"])
	require.Equal(t, true, result["d_Post-bureauAffordability"])
	require.Equal(t, "ACCEPT", result["d_Routing"])
}

