func TestTCK_0007_date_time_001(t *testing.T) {
	d := mustParse("testdata/tck/TestCases/compliance-level-3/0007-date-time/0007-date-time.dmn")
	inputs := map[string]any{
		"dateString":     "2015-12-24",
		"timeString":     "00:00:01-01:00",
		"dateTimeString": "2016-12-24T23:59:00-08:00",
		"Hours":          float64(12),
		"Minutes":        float64(59),
		"Seconds":        float64(01.3),
		"Timezone":       "-PT1H",
		"Year":           float64(1999),
		"Month":          float64(11),
		"Day":            float64(22),
		"oneHour":        "PT1H",
		"durationString": "P13DT2H14S",
	}
	result, err := d.Evaluate(inputs)
	require.NoError(t, err)
	require.Equal(t, "2016-12-24T23:59:00-08:00", result["_dfbb843a-bd34-4099-b700-0d9ca5b38d6a"])
	require.Equal(t, "", result["_bd547a08-c157-47ca-84d4-ac6f3d5bdeda"])
	require.Equal(t, "00:00:01-01:00", result["_9e8acf47-790a-4741-8ebb-e8a22a30744c"])
	require.Equal(t, "2015-12-24T00:00:01-01:00", result["_7df22028-4b5b-4594-89c7-a80b8aec526f"])
	require.Equal(t, "00:00:01-01:00", result["_1f2b08ce-3c6b-4e22-a747-8d9f378e9035"])
	require.Equal(t, "12:59:01.3-01:00", result["_463b1a36-2505-413a-8056-f6a5efc2b52e"])
	require.Equal(t, "P13DT2H14S", result["_972ecd98-1c70-4f0c-909c-786f23c61dbb"])
	require.Equal(t, "P367DT6H58M59S", result["_a2c48b03-6e72-4846-99cc-02f3747c6867"])
	require.Equal(t, "P380DT8H59M13S", result["_14f9f361-8c3c-455b-9c97-fe15201e3b5e"])
	require.Equal(t, "P1Y0M", result["_cbac111e-ca71-4fac-a921-175ffd767055"])
	require.Equal(t, float64(24), result["_04c6bedc-bc63-464f-8e61-c039d24a47bf"])
	require.Equal(t, float64(2015), result["_dc18ebe0-6762-4734-aeb3-ed4fb861865c"])
	require.Equal(t, float64(12), result["_2cf37ed0-590d-4f97-b58b-46eaa424b965"])
	require.Equal(t, float64(0), result["_087e3f57-8ea6-4857-a080-fadc5a1dd9e8"])
	require.Equal(t, float64(0), result["_6836a944-7f7b-4c98-8a7a-a573494110fd"])
	require.Equal(t, float64(1), result["_4af88a8f-92e4-4f2d-bde1-e8a36b27e5bf"])
	require.Equal(t, "-PT1H", result["_81f97dd0-29ea-4bab-9540-b70a2fdf8ff3"])
	require.Equal(t, float64(1), result["_91fb395d-8173-4ed3-95f7-f790bd3967ab"])
	require.Equal(t, float64(14), result["_c2f1a1ae-1403-43a2-b176-dedf3da51e6b"])
}

