func TestTCK_0036_dt_variable_input__20445ee0_744d_4488_a90e_136701510871(t *testing.T) {
	d := mustParse("testdata/tck/TestCases/compliance-level-3/0036-dt-variable-input/0036-dt-variable-input.dmn")
	inputs := map[string]any{
		"Complex":                           map[string]any{"aBoolean": true, "aNumber": float64(10), "aString": "\"Hi\"", "aDate": "2018-07-30", "aTime": "16:11:00", "aDateTime": "2018-07-30T16:12:00Z", "aDaysAndTimeDuration": "PT10H", "aYearsAndMonthsDuration": "P5M"},
		"Another boolean":                   false,
		"Another String":                    "\"Hello\"",
		"Another number":                    float64(15),
		"Another Date":                      "2018-07-31",
		"Another Time":                      "17:13:00",
		"Another Date and Time":             "2018-07-31T17:13:00Z",
		"Another Days and Time Duration":    "PT12H",
		"Another Years and Months Duration": "P8M",
	}
	result, err := d.Evaluate(inputs)
	require.NoError(t, err)
	require.Equal(t, "Different String", result["_4f421adb-316c-42e0-b6ff-5243c365bdba"])
	require.Equal(t, "Future Date", result["_6ea508a1-3414-4023-815c-1c9f9eb76604"])
	require.Equal(t, "Bigger", result["_35583bbe-81b8-4797-afe9-d870c3e17d44"])
	require.Equal(t, "Future date time", result["_65c8e959-50df-4fd5-931c-be8e22f0005a"])
	require.Equal(t, "Longer duration", result["_88012dbc-db14-4c87-83b0-164a0f3fe602"])
	require.Equal(t, "Longer duration", result["_57cd8fab-8d6a-4a04-9f96-b04ae1674bf4"])
	require.Equal(t, "Future Time", result["_d6407854-040f-4122-8173-3d3e266c6649"])
	require.Equal(t, "Not same boolean", result["_29fcbd74-791b-4700-b6b9-93654a21f492"])
}

