func TestTCK_1155_list_replace_function_001(t *testing.T) {
	d := mustParse("testdata/tck/TestCases/compliance-level-3/1155-list-replace-function/1155-list-replace-function.dmn")
	inputs := map[string]any{}
	result, err := d.Evaluate(inputs)
	require.NoError(t, err)

	dRes := result["_decision001"]

	vSlice, isSlice := dRes.([]any)
	require.True(t, isSlice)

	expected := []feel.Number{
		*feel.N(1),
		*feel.N(4),
		*feel.N(3),
	}

	for i, vNum := range vSlice {
		fNum, isNum := vNum.(*feel.Number)
		require.True(t, isNum)

		require.Equal(t, expected[i].Int64(), fNum.Int64())
	}
}

